waves.point_eqs_str:
//rotating sphere

n = sample*6.283;
n2 = sample*2.1415;

scale = above( sin(n*256) , 0 )*0.1 + 0.5;
scale = scale ;

//draw circle, loop 32x
xp = sin(n2)*scale;
yp = cos(n2)*scale;
zp = 0 ;

t2 = t2 + 0.125;

t3 = t3 + 1;
t3 = t3 * below( t3 , 8 );
sig = sign( t3 - 3.5 );

//a = below( t3 , 5 );


//turn circle into sphere, by rotating on y axis once during frame
ang = 0;//n;//int(t2)/60 * 6.283 * 2;
sang = sin(ang);cang = cos(ang);
xq = xp*cang - zp*sang;
yq = yp;
zq = xp*sang + zp*cang;
xp=xq;yp=yq;zp=zq;


//x axis rotation;
ang = t1;
sang = sin(ang);cang = cos(ang);
xq = xp;
yq = yp*cang - zp*sang;
zq = yp*sang + zp*cang;
xp=xq;yp=yq;zp=zq;

//y axis rotation;
ang = t1*18;
sang = sin(ang);cang = cos(ang);
xq = xp*cang - zp*sang;
yq = yp;
zq = xp*sang + zp*cang;
xp=xq;yp=yq;zp=zq;

//z axis rotation;
ang = t1*3;
sang = sin(ang);cang = cos(ang);
xq = xp*cang - yp*sang;
yq = xp*sang + yp*cang;
zq = zp;
xp=xq;yp=yq;zp=zq;

//push forward into viewspace
zp = zp + 2;

fov = 1; //larger number equal less extreme perspective (zoom in)

//project into camera space, and compensate for aspect ratio
x = xp/zp * fov + 0.75;
y = yp/zp * 1.3333 * fov + 0.75;

//x = x + t6;
//x = x - int(x);

x = max( x , 0.5 );
y = max( y , 0.5 );

flux = abs(sample-0.5)*2;
r = r * flux;
g = pow( g , flux+0.2 );



bkill = 1 - equal(x,0.5);
bkill = bkill * (1-equal(y,0.5));
a = a * bkill;

